S['CH0412A'] = [{'k': 'hook', 'ch': 'Mở đầu', 'label': 'Hòa Phát', 'cap': ('LÃI GẤP ĐÔI', 'GIÁ GIẢM 20%?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Steel coils loaded on truck deck.jpg', 'chart': {'sym': 'HPGW', 'weeks': 52, 'circles': [[14, 26.51, 'Đỉnh tuần 23/2/26: 26,51', 0.6], [45, 19.6, 'Đáy tuần 28/9/26: 19,60', 1.6], [51, 21.25, 'Tuần 9/11/26: 21,25', 2.6]]}, 'say': 'Quý ba năm nay, Hòa Phát lãi tám nghìn hai trăm sáu mươi lăm tỷ đồng, gấp đôi cùng kỳ năm ngoái. Cũng trong lúc đó, cổ phiếu Hòa Phát lại thấp hơn đỉnh hồi tháng hai khoảng hai mươi phần trăm, chỉ cách đáy năm mươi hai tuần chừng tám phần trăm.'}, {'k': 'bignum', 'cap': ('LỢI NHUẬN QUÝ 3', 'TĂNG 106%'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': 8265, 'fmt': '{:,.0f}', 'unit': ' tỷ', 'top': 'LÃI SAU THUẾ QUÝ 3/2026', 'sub': 'cùng kỳ 2025: 4.012 tỷ', 'col': (34, 197, 94), 'anh': 'File:A bunch of rebar up close.jpg', 'say': 'Lợi nhuận tăng gấp đôi mà giá lại đi xuống. Vậy thị trường đang ngớ ngẩn, hay thị trường đang biết một điều mà người chỉ nhìn con số lợi nhuận chưa thấy?'}, {'k': 'text', 'cap': ('34.500 TỶ', 'RỒI MẤT 3/4'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:DSC03739 Blast Furnace 1 at Night, voestalpine Donawitz, 2026-02.jpg', 'anh_them': ['File:Iron ore pellets from Kiruna.jpg'], 'the': [{'f': 0.05, 'so': '34.521 tỷ', 'nhan': 'Lãi năm 2021 – kỷ lục của Hòa Phát'}, {'f': 0.5, 'so': '8.444 tỷ', 'nhan': 'Lãi năm 2022 – giảm 76%'}], 'say': 'Gợi ý nằm ở chính lịch sử của Hòa Phát. Năm hai nghìn không trăm hai mươi mốt, công ty lãi kỷ lục hơn ba mươi bốn nghìn tỷ đồng. Chỉ một năm sau, lợi nhuận mất ba phần tư. Xem hết video này, anh chị sẽ biết một tấn thép Hòa Phát đang giữ lại bao nhiêu tiền, và lãi gấp đôi đến từ đâu. Em cũng sẽ chỉ ra phần nào bền, phần nào có thể mất, cùng ba câu hỏi để soi bất kỳ cổ phiếu chu kỳ nào trước khi mua.'}, {'k': 'cards', 'ch': 'Chương 1 – Một tấn thép giữ lại bao nhiêu?', 'cap': ('MỘT TẤN THÉP', 'GIỮ LẠI BAO NHIÊU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Iron ore pellets from Kiruna.jpg', 'cards': [('3,8 triệu tấn', 'thép bán ra quý 3/2026', ''), ('≈16,5 triệu đ', 'doanh thu mỗi tấn (tính thô)', ''), ('≈2,17 triệu đ', 'lợi nhuận mỗi tấn (tính thô)', '')], 'say': 'Hòa Phát làm nghề rất dễ hình dung. Công ty mua quặng sắt và than, nấu trong lò cao thành phôi thép, rồi cán ra thép xây dựng và thép cuộn cán nóng. Quý ba, công ty bán khoảng ba phẩy tám triệu tấn các loại thép chính. Em chia thô doanh thu cả tập đoàn cho số tấn này, mỗi tấn mang về khoảng mười sáu phẩy năm triệu đồng. Còn lợi nhuận sau thuế chia cho số tấn, mỗi tấn giữ lại khoảng hai phẩy mười bảy triệu đồng.'}, {'k': 'cards', 'cap': ('MỘT TẤN THÉP', 'GIỮ LẠI BAO NHIÊU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Rusty rebar nets.jpg', 'cards': [('≈1,62 triệu đ', 'lãi mỗi tấn quý 3/2025', ''), ('≈2,17 triệu đ', 'lãi mỗi tấn quý 3/2026', ''), ('+34%', 'mỗi tấn lãi thêm', '')], 'say': 'Đây là phép chia thô, vì doanh thu và lợi nhuận còn có ống thép, tôn, nông nghiệp. Nhưng để so sánh thì đủ dùng. Cùng cách tính, quý ba năm ngoái mỗi tấn chỉ giữ lại khoảng một phẩy sáu mươi hai triệu đồng. Nghĩa là mỗi tấn thép bây giờ lãi hơn khoảng ba mươi bốn phần trăm. Nghe thì có vẻ đây là toàn bộ câu chuyện. Nhưng thật ra nó mới chỉ là một nửa.'}, {'k': 'bars', 'ch': 'Chương 2 – Hai động cơ của lãi gấp đôi', 'cap': ('LÃI GẤP ĐÔI', 'ĐẾN TỪ ĐÂU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Steel coils loaded on truck deck.jpg', 'tag': 'QUÝ 3/2026 SO VỚI QUÝ 3/2025', 'bars': [('Sản lượng bán', 1.54, (56, 189, 248), '× 1,54'), ('Lãi mỗi tấn', 1.34, (255, 196, 0), '× 1,34'), ('Lợi nhuận', 2.06, (34, 197, 94), '× 2,06')], 'say': 'Lợi nhuận là tích của hai thứ: bán được bao nhiêu tấn, và mỗi tấn lãi bao nhiêu. Sản lượng bán quý ba tăng năm mươi bốn phần trăm, tức là gấp một phẩy năm mươi bốn lần. Lãi mỗi tấn gấp khoảng một phẩy ba mươi bốn lần. Nhân hai con số này với nhau ra khoảng hai phẩy không sáu lần, đúng bằng mức lợi nhuận tăng gấp đôi. Vậy là có hai động cơ chạy cùng lúc.'}, {'k': 'text', 'cap': ('ĐỘNG CƠ 1', 'DUNG QUẤT 2'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Kaltbandcoils.jpg', 'anh_them': ['File:Steel Coils - Leeco Steel - Antonio Rosset.jpg'], 'the': [{'f': 0.05, 'so': '> 2 triệu tấn', 'nhan': 'HRC bán ra quý 3/2026, +64% so với cùng kỳ'}, {'f': 0.55, 'so': '23,1–27,83%', 'nhan': 'Thuế chống bán phá giá HRC Trung Quốc từ 7/2025'}], 'say': 'Động cơ thứ nhất là sản lượng, và nó đến từ khu liên hợp Dung Quất hai ở Quảng Ngãi. Thép cuộn cán nóng là loại thép làm nguyên liệu cho tôn, ống thép, đồ gia dụng. Riêng loại này, Hòa Phát bán hơn hai triệu tấn trong quý ba, tăng sáu mươi bốn phần trăm. Thêm vào đó, từ tháng bảy năm hai nghìn không trăm hai mươi lăm, thép cán nóng nhập từ Trung Quốc bị áp thuế chống bán phá giá từ hai mươi ba phẩy một đến hai mươi bảy phẩy tám mươi ba phần trăm. Nhờ vậy, hàng trong nước có thêm chỗ đứng.'}, {'k': 'text', 'cap': ('ĐỘNG CƠ 2', 'GIÁ VÀ CHI PHÍ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Hot Strip Mill (29897131).jpeg', 'anh_them': ['File:Colored steel coils.jpg'], 'the': [{'f': 0.05, 'so': '19,2%', 'nhan': 'Biên lợi nhuận gộp quý 3/2026 (cùng kỳ 16,7%)'}, {'f': 0.5, 'so': '≈8.798 tỷ', 'nhan': 'Tiết kiệm nhờ tự chủ 90% điện (10 tháng 2026)'}], 'say': 'Động cơ thứ hai là mỗi tấn lãi hơn. Biên lợi nhuận gộp quý ba lên mười chín phẩy hai phần trăm, cùng kỳ chỉ mười sáu phẩy bảy phần trăm. Chính Hòa Phát giải thích lợi nhuận tăng do tiêu thụ tăng, giá vốn tốt và giá bán tốt. Công ty cũng tự chủ khoảng chín mươi phần trăm lượng điện cho sản xuất thép, theo công bố là tiết kiệm tương đương gần tám nghìn tám trăm tỷ đồng trong mười tháng. Bây giờ mới đến câu hỏi quan trọng nhất: trong hai động cơ này, động cơ nào bền?'}, {'k': 'text', 'cap': ('MỘT ĐỘNG CƠ BỀN', 'MỘT ĐỘNG CƠ THEO MÙA'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:A bunch of rebar up close.jpg', 'say': 'Sản lượng đến từ nhà máy mới, máy móc đã xây xong, nên phần này tương đối bền, miễn là còn bán được hàng. Còn lãi mỗi tấn phụ thuộc giá thép, giá quặng, giá than, những thứ Hòa Phát không quyết định được. Phần này lên xuống theo chu kỳ, như thời tiết vậy.'}, {'k': 'cards', 'cap': ('97% DOANH THU', 'CHỈ 77% LỢI NHUẬN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Iron ore pellets from Kiruna.jpg', 'cards': [('97%', 'doanh thu 9 tháng đến từ thép', ''), ('77%', 'lợi nhuận 9 tháng đến từ thép', ''), ('≈5.500 tỷ', '23% lợi nhuận còn lại', '')], 'say': 'Còn một chi tiết nữa trong công bố chín tháng. Thép đóng góp chín mươi bảy phần trăm doanh thu, nhưng chỉ bảy mươi bảy phần trăm lợi nhuận. Mảng nông nghiệp có bán ra ba trăm sáu mươi lăm nghìn con heo, hai trăm bảy mươi bốn nghìn tấn thức ăn chăn nuôi và gần hai trăm năm mươi tám triệu quả trứng, nhưng quy mô doanh thu chỉ khoảng ba phần trăm. Vậy mà hai mươi ba phần trăm lợi nhuận còn lại tương đương khoảng năm nghìn năm trăm tỷ đồng, lớn bất thường so với ba phần trăm doanh thu. Phần chênh này đến từ đâu?'}, {'k': 'bignum', 'ch': 'Chương 3 – Khoản lãi không lặp lại', 'cap': ('KHOẢN LÃI', 'KHÔNG LẶP LẠI'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': 4929, 'fmt': '{:,.0f}', 'unit': ' tỷ', 'top': 'THU TỪ BÁN CÔNG TY CON', 'sub': 'ghi nhận trong 6 tháng đầu 2026', 'col': (255, 196, 0), 'anh': 'File:Ho Chi Minh City Skyline.jpg', 'say': 'Câu trả lời nằm ở một chi tiết nhỏ trong thuyết minh mà nhiều người bỏ qua. Lũy kế chín tháng, Hòa Phát lãi hai mươi ba nghìn bảy trăm bốn mươi sáu tỷ đồng, đã vượt tám phần trăm kế hoạch cả năm. Nhưng trong nửa đầu năm, công ty đã bán toàn bộ cổ phần ở một số công ty con. Thương vụ này mang về bốn nghìn chín trăm hai mươi chín tỷ đồng doanh thu tài chính, gần bằng toàn bộ phần lợi nhuận ngoài thép em vừa nói.'}, {'k': 'bignum', 'cap': ('KHOẢN LÃI', 'KHÔNG LẶP LẠI'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': 4929, 'fmt': '{:,.0f}', 'unit': ' tỷ', 'top': 'THU TỪ BÁN CÔNG TY CON', 'sub': 'không phải tiền từ bán thép', 'col': (255, 196, 0), 'anh': 'File:Ho Chi Minh City Skyline.jpg', 'say': 'Khoản này không đến từ việc bán thép và sẽ không lặp lại mỗi năm. Tin tốt là quý ba không dựa vào khoản này: tám nghìn hai trăm sáu mươi lăm tỷ của quý ba chủ yếu là tiền từ thép. Bài học ở đây rất đơn giản: con số lũy kế đẹp chưa chắc là năng lực kiếm tiền lặp lại được. Trước khi vui, anh chị nên tìm dòng doanh thu tài chính và thu nhập khác.'}, {'k': 'cards', 'cap': ('BỎ KHOẢN MỘT LẦN', 'CÒN LẠI BAO NHIÊU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Ho Chi Minh City Skyline.jpg', 'cards': [('23.746 tỷ', 'lãi sau thuế 9 tháng 2026', ''), ('≈ 18.800 tỷ', 'nếu trừ 4.929 tỷ (tính thô, chưa trừ thuế)', ''), ('≈ 85%', 'kế hoạch năm 22.000 tỷ', '')], 'say': 'Em thử trừ thô khoản này ra. hai mươi ba nghìn bảy trăm bốn mươi sáu tỷ trừ bốn nghìn chín trăm hai mươi chín tỷ còn khoảng mười tám nghìn tám trăm tỷ. Phép trừ này chưa tính thuế nên chỉ để hình dung, nhưng kết luận khá rõ. Kế hoạch cả năm của Hòa Phát là hai mươi hai nghìn tỷ, nên phần lãi từ hoạt động chính sau chín tháng vẫn đạt khoảng tám mươi lăm phần trăm kế hoạch. Nghĩa là năng lực kiếm tiền từ thép năm nay là thật, chỉ là không đẹp như con số một trăm linh tám phần trăm kế hoạch mà nhiều tin tức nhắc tới.'}, {'k': 'checklist', 'ch': 'Chương 4 – Thị trường đang lo điều gì?', 'cap': ('THỊ TRƯỜNG', 'ĐANG LO GÌ?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Steel coils loaded on truck deck.jpg', 'items': [('Giá thép thành phẩm hạ nhiệt', (239, 68, 68)), ('Chi phí lãi vay +118%', (239, 68, 68)), ('Mexico áp 285,5 USD/tấn HRC', (239, 68, 68)), ('Thép Ấn Độ nhập gấp 11 lần', (239, 68, 68))], 'say': 'Vậy vì sao lợi nhuận gấp đôi mà giá vẫn yếu? Em thấy bốn mối lo. Một, từ quý ba, giá thép thành phẩm trên thị trường đã bắt đầu hạ nhiệt. Hai, chi phí lãi vay quý ba tăng một trăm mười tám phần trăm. Em đoán một nguyên nhân hợp lý là khi Dung Quất hai đã chạy, tiền lãi của các khoản vay xây nhà máy không còn được cộng vào giá trị công trình. Khoản lãi đó giờ phải tính thẳng vào chi phí.'}, {'k': 'checklist', 'cap': ('THỊ TRƯỜNG', 'ĐANG LO GÌ?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Steel coils loaded on truck deck.jpg', 'items': [('Giá thép thành phẩm hạ nhiệt', (239, 68, 68)), ('Chi phí lãi vay +118%', (239, 68, 68)), ('Mexico áp 285,5 USD/tấn HRC', (239, 68, 68)), ('Thép Ấn Độ nhập gấp 11 lần', (239, 68, 68))], 'say': 'Ba, xuất khẩu khó hơn: tháng chín, Mexico chốt thuế chống bán phá giá hai trăm tám mươi lăm phẩy năm đô la Mỹ mỗi tấn với thép cuộn cán nóng của Hòa Phát Dung Quất. Bốn, khi hàng Trung Quốc bị áp thuế, thép từ Ấn Độ chen vào: chín tháng năm nay, Việt Nam nhập gần một triệu tấn sắt thép từ Ấn Độ, gấp hơn mười một lần cùng kỳ. Và ngay phiên chín tháng mười một, Hòa Phát là mã bị khối ngoại bán ròng mạnh nhất.'}, {'k': 'text', 'ch': 'Chương 5 – Bài học năm 2022', 'cap': ('ĐỈNH LỢI NHUẬN', 'LẠI LÀ LÚC NGUY HIỂM?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Hot Strip Mill, Llanwern Steelworks - geograph.org.uk - 3635746.jpg', 'anh_them': ['File:Steel coils loaded on truck deck.jpg'], 'the': [{'f': 0.05, 'so': '23% → −3%', 'nhan': 'Biên lợi nhuận gộp Hòa Phát quý 1/2022 → quý 4/2022'}, {'f': 0.55, 'so': '−25%', 'nhan': 'Giá thép xây dựng từ giữa tháng 5/2022, 19 lần giảm liên tiếp'}], 'say': 'Để hiểu vì sao người ta dè dặt, mình quay lại năm hai nghìn không trăm hai mươi hai. Quý một năm đó, biên lợi nhuận gộp của Hòa Phát khoảng hai mươi ba phần trăm. Rồi từ giữa tháng năm, giá thép xây dựng giảm gần như liên tục mười chín lần, tổng cộng khoảng hai mươi lăm phần trăm. Đến quý bốn, biên lợi nhuận gộp âm ba phần trăm, công ty lỗ gần hai nghìn tỷ đồng trong một quý.'}, {'k': 'text', 'cap': ('CHU KỲ THÉP', 'CHẠY THẾ NÀO?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Rebar Tying in Rawanduz.jpg', 'anh_them': ['File:A bunch of rebar up close.jpg'], 'the': [{'f': 0.05, 'ds': ['Nhà ở, hạ tầng xây nhiều → cần nhiều thép', 'Giá thép tăng → nhà máy chạy hết công suất, mở rộng', 'Cung tăng, cầu chậm lại → giá giảm', 'Hàng tồn kho giá cao → lỗ'], 'tieu': 'VÒNG QUAY CHU KỲ'}], 'say': 'Chu kỳ thép thường chạy theo một vòng khá quen. Khi nhà ở và hạ tầng xây nhiều, nhu cầu thép tăng, giá thép tăng, các nhà máy chạy hết công suất và đầu tư thêm. Rồi đến lúc nguồn cung tăng nhanh hơn nhu cầu, giá quay đầu giảm. Doanh nghiệp đang ôm quặng, than mua giá cao thì bị kẹp giữa. Năm hai nghìn không trăm hai mươi hai, chính Hòa Phát viết trong báo cáo thường niên rằng thị trường bất động sản ảm đạm nửa cuối năm khiến nhu cầu thép trong nước giảm. Thép xây dựng khi đó chiếm hơn bảy mươi phần trăm lượng tiêu thụ nội địa của công ty.'}, {'k': 'bars', 'cap': ('34.521 TỶ', 'CÒN 8.444 TỶ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Ho Chi Minh City Skyline (night).jpg', 'tag': 'LỢI NHUẬN SAU THUẾ HÒA PHÁT (TỶ ĐỒNG)', 'bars': [('2021', 34521, (34, 197, 94), '34.521'), ('2022', 8444, (239, 68, 68), '8.444'), ('9T/2026', 23746, (255, 196, 0), '23.746')], 'say': 'Cả năm hai nghìn không trăm hai mươi hai, lợi nhuận còn tám nghìn bốn trăm bốn mươi bốn tỷ, giảm bảy mươi sáu phần trăm so với năm kỷ lục hai nghìn không trăm hai mươi mốt. Ai nhìn P trên E năm hai nghìn không trăm hai mươi mốt sẽ thấy cổ phiếu rất rẻ, vì lợi nhuận quá lớn. Nhưng chính lúc đó lại là đỉnh. Đây là nghịch lý nổi tiếng của cổ phiếu chu kỳ: P trên E thấp nhất thường xuất hiện đúng lúc lợi nhuận đang ở đỉnh. Và người mua vì thấy rẻ lại thường là người chịu thiệt nhiều nhất.'}, {'k': 'cards', 'ch': 'Chương 6 – Lần này khác ở đâu?', 'cap': ('LẦN NÀY', 'CÓ KHÁC?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Kaltbandcoils.jpg', 'cards': [('6,4 lần', 'P/E hiện tại', ''), ('19,9%', 'ROE', ''), ('1,19 lần', 'P/B', '')], 'say': 'Nhưng khoan, đừng vội kết luận lịch sử sẽ lặp lại y hệt. Hiện Hòa Phát có P trên E khoảng sáu phẩy bốn lần, P trên B một phẩy mười chín lần, ROE gần hai mươi phần trăm. Điểm khác năm hai nghìn không trăm hai mươi mốt là lần này lợi nhuận được kéo bởi cả sản lượng mới từ Dung Quất hai, chứ không chỉ bởi giá thép. Bảng P trên E, lợi nhuận từng quý của Hòa Phát và hơn bốn trăm mã khác, em để sẵn trên chứng khoán Huy Nguyễn chấm com để anh chị tự đối chiếu.'}, {'k': 'cards', 'cap': ('NẾU LÃI MỖI TẤN', 'VỀ NHƯ NĂM NGOÁI?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Rusty rebar nets.jpg', 'cards': [('3,8 tr tấn × 4 quý', 'giữ sản lượng hiện tại', ''), ('× 1,62 tr đ/tấn', 'lãi mỗi tấn như quý 3/2025', ''), ('≈ 24.600 tỷ/năm', 'P/E ≈ 7,2 lần', '')], 'say': 'Em thử một kịch bản xấu vừa phải. Giả sử sản lượng giữ được ba phẩy tám triệu tấn mỗi quý, nhưng lãi mỗi tấn quay về mức một phẩy sáu mươi hai triệu đồng như quý ba năm ngoái. Lợi nhuận một năm khi đó khoảng hai mươi bốn nghìn sáu trăm tỷ, và với giá hiện tại P trên E vào khoảng bảy phẩy hai lần. Còn kịch bản rất xấu là biên lợi nhuận sụp như năm hai nghìn không trăm hai mươi hai, khi đó mọi phép tính P trên E hôm nay đều không còn ý nghĩa. Em không biết kịch bản nào sẽ xảy ra, và cũng không ai biết chắc. Nhưng biết trước hai kịch bản giúp anh chị không bị bất ngờ.'}, {'k': 'checklist', 'ch': 'Chương 7 – Ba câu hỏi cho cổ phiếu chu kỳ', 'cap': ('3 CÂU HỎI', 'CỔ PHIẾU CHU KỲ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:A bunch of rebar up close.jpg', 'items': [('Lãi tăng vì sản lượng hay vì giá?', (255, 196, 0)), ('Có khoản lãi một lần không?', (255, 196, 0)), ('Lãi về trung bình thì P/E bao nhiêu?', (255, 196, 0))], 'say': 'Gói lại thành ba câu hỏi anh chị dùng được cho thép, phân bón, hóa chất, vận tải biển, bất kỳ ngành chu kỳ nào. Một, lợi nhuận tăng vì bán nhiều hơn, hay vì giá bán đang cao? Phần đến từ năng lực mới thường bền hơn phần đến từ giá. Hai, trong lợi nhuận có khoản nào chỉ xảy ra một lần không, như bán công ty con, hoàn nhập dự phòng? Ba, nếu biên lợi nhuận quay về mức trung bình nhiều năm, P trên E thật sự là bao nhiêu? Nếu con số đó vẫn chấp nhận được, anh chị đang mua với biên an toàn. Nếu không, cái rẻ hôm nay có thể chỉ là ảo giác của đỉnh chu kỳ.'}, {'k': 'text', 'cta': 1, 'label': 'TÀI LIỆU KÈM VIDEO', 'cap': ('BẢNG SỐ 400+ MÃ', 'CHUNGKHOANHUYNGUYEN.COM'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Số liệu trong video lấy từ báo cáo tài chính và công bố của Hòa Phát, cập nhật đến quý ba năm hai nghìn không trăm hai mươi sáu. Anh chị muốn trao đổi riêng về danh mục thì nhắn Zalo không ba sáu năm, một tám tám, hai tám sáu.'}, {'k': 'end', 'cap': ('ĐỈNH CHU KỲ', 'HAY NỀN MỚI?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Còn anh chị, anh chị nghĩ lợi nhuận Hòa Phát lần này là đỉnh của một chu kỳ, hay là một mặt bằng mới nhờ Dung Quất hai? Anh chị để lại suy nghĩ ở phần bình luận, em đọc hết.'}]
S['CH0512A'] = [{'k': 'hook', 'ch': 'Mở đầu', 'label': 'Vietjet', 'cap': ('BAY 1 KHÁCH', 'LÃI 48 NGHÌN?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Vietjet Air Airbus A321-211(WL) VN-A657.jpg', 'chart': {'sym': 'VJCW', 'weeks': 52, 'circles': [[2, 169.22, 'Đỉnh tuần 24/11/25: 169,22', 0.6], [16, 111.92, 'Đáy tuần 9/3/26: 111,92', 1.6], [51, 136.4, 'Tuần 9/11/26: 136,40', 2.6]]}, 'say': 'Quý ba năm nay, Vietjet chở khoảng bảy phẩy ba triệu lượt khách và lãi sau thuế ba trăm bốn mươi tám tỷ đồng. Chia ra, mỗi lượt khách mang về cho hãng khoảng bốn mươi tám nghìn đồng, chưa bằng một bát phở và một ly cà phê ở sân bay.'}, {'k': 'cards', 'cap': ('DOANH THU +35%', 'KHÁCH CHỈ +3,3%'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Tan Son Nhat International Terminal (08.2026).jpg', 'cards': [('+35%', 'doanh thu quý 3/2026', ''), ('+3,3%', 'lượt khách', ''), ('+2,4%', 'số chuyến bay', '')], 'say': 'Lạ hơn nữa là doanh thu quý ba tăng ba mươi lăm phần trăm, trong khi số khách chỉ tăng ba phẩy ba phần trăm và số chuyến bay tăng hai phẩy bốn phần trăm. Khách gần như đứng yên, vậy mà doanh thu tăng hơn một phần ba. Vậy phần tiền tăng thêm đó ở đâu ra?'}, {'k': 'text', 'cap': ('LÃI KHÔNG ĐẾN', 'TỪ VIỆC BAY?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Vietjet Air Airbus A321-271N (A321neo) reg. VN-A674.jpg', 'the': [{'f': 0.1, 'so': '7,3 triệu', 'nhan': 'lượt khách quý 3/2026 trên 39 nghìn chuyến bay'}], 'say': 'Em đã mở thuyết minh báo cáo tài chính quý ba của Vietjet và đọc từng dòng doanh thu, giá vốn. Câu trả lời khá bất ngờ: trong quý này, phần lớn lợi nhuận gộp không đến từ việc chở khách. Xem hết video, anh chị sẽ biết một tấm vé giá rẻ được chia làm mấy phần, và mảng nào đang gánh lợi nhuận. Cuối video là ba câu hỏi để không bị con số doanh thu đánh lừa ở bất kỳ doanh nghiệp nào.'}, {'k': 'cards', 'ch': 'Chương 1 – Một tấm vé chia làm mấy phần?', 'cap': ('MỘT LƯỢT KHÁCH', 'MANG VỀ BAO NHIÊU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Airbus A321 aircraft cabin, Baku to İstanbul.jpg', 'cards': [('≈1,04 triệu đ', 'tiền vé mỗi lượt khách', ''), ('≈843 nghìn đ', 'dịch vụ phụ trợ mỗi lượt', ''), ('≈81%', 'phụ trợ so với tiền vé', '')], 'say': 'Bắt đầu bằng mô hình hàng không giá rẻ. Hãng bán vé thật rẻ để kéo khách lên máy bay. Sau đó hãng thu thêm từ hành lý ký gửi, chọn chỗ ngồi, suất ăn, đổi vé, hàng miễn thuế. Quý ba, doanh thu vé nội địa và quốc tế cộng lại khoảng bảy nghìn sáu trăm mười ba tỷ đồng, chia cho bảy phẩy ba triệu lượt khách thì mỗi lượt khoảng một phẩy không bốn triệu đồng tiền vé. Còn doanh thu phụ trợ là sáu nghìn một trăm năm mươi lăm tỷ, tức khoảng tám trăm bốn mươi ba nghìn đồng mỗi lượt.'}, {'k': 'cards', 'cap': ('MỘT LƯỢT KHÁCH', 'MANG VỀ BAO NHIÊU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Zuerich airport-Baggage conveyor belt baggage claim-01ASD.jpg', 'cards': [('≈1,19 triệu đ', 'tiền vé mỗi lượt quý 3/2025', ''), ('≈1,04 triệu đ', 'tiền vé mỗi lượt quý 3/2026', ''), ('−12,5%', 'tiền vé mỗi lượt khách', '')], 'say': 'Nghĩa là cứ một đồng tiền vé, hãng thu thêm gần tám hào từ dịch vụ đi kèm. Đây là cách mọi hãng giá rẻ trên thế giới kiếm tiền. Nhưng có một chi tiết đáng chú ý: cùng cách tính, quý ba năm ngoái mỗi lượt khách trả khoảng một phẩy mười chín triệu đồng tiền vé. Năm nay chỉ còn khoảng một phẩy không bốn triệu, giảm khoảng mười hai phẩy năm phần trăm. Khách tăng, mà tiền vé thu về lại ít đi.'}, {'k': 'text', 'cap': ('VÉ 0 ĐỒNG', 'VẪN CÓ LỜI?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Airbus A321 aircraft cabin, Baku to İstanbul.jpg', 'anh_them': ['File:Tan Son Nhat Airport domestic hall.JPG'], 'say': 'Nhiều người thắc mắc, bán vé không đồng thì lời ở đâu. Bí mật nằm ở chỗ: khi máy bay đã quyết định cất cánh, nhiên liệu, tổ bay, phí sân bay gần như đã phải trả. Chở thêm một khách vào ghế trống chỉ tốn thêm rất ít. Vì vậy hãng sẵn sàng bán rẻ những ghế khó bán để lấp đầy máy bay, rồi kiếm lại từ hành lý, suất ăn, chọn chỗ. Mô hình này chạy tốt khi chi phí mỗi chuyến ổn định. Nhưng khi chi phí mỗi chuyến tăng mạnh, như quý ba năm nay, vé rẻ trở thành gánh nặng.'}, {'k': 'bars', 'ch': 'Chương 2 – Doanh thu tăng 35% đến từ đâu?', 'cap': ('DOANH THU TĂNG', 'NHỜ MẢNG NÀO?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Vietjet Air VN-A687 09-07-2024.jpg', 'tag': 'DOANH THU QUÝ 3/2026', 'bars': [('Tiền vé', 7613, (239, 68, 68), '7.613 tỷ'), ('Phụ trợ', 6155, (56, 189, 248), '6.155 tỷ'), ('Thuê chuyến', 3008, (255, 196, 0), '3.008 tỷ'), ('Tàu bay', 4356, (34, 197, 94), '4.356 tỷ')], 'say': 'Giờ mình tách doanh thu hai mươi hai nghìn tám trăm bốn mươi chín tỷ ra từng mảng. Tiền vé giảm chín phẩy sáu phần trăm so với cùng kỳ. Phụ trợ gần như đi ngang, tăng một phẩy tám phần trăm. Doanh thu cho thuê chuyến bay, tức là cho đối tác thuê cả chuyến kèm tổ bay, tăng gấp hai phẩy một lần, lên khoảng ba nghìn tỷ.'}, {'k': 'bars', 'cap': ('DOANH THU TĂNG', 'NHỜ MẢNG NÀO?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Vietjet Air VN-A687 09-07-2024.jpg', 'tag': 'THAY ĐỔI SO VỚI QUÝ 3/2025', 'bars': [('Tiền vé', 9.6, (239, 68, 68), '−9,6%'), ('Phụ trợ', 1.8, (56, 189, 248), '+1,8%'), ('Thuê chuyến', 110, (255, 196, 0), '×2,1'), ('Tàu bay', 902, (34, 197, 94), '×10')], 'say': 'Và dòng tăng mạnh nhất có cái tên rất dài trong thuyết minh: thu xếp, chuyển quyền sở hữu và thương mại tàu bay, động cơ. Quý ba năm ngoái dòng này khoảng bốn trăm ba mươi lăm tỷ. Quý ba năm nay là bốn nghìn ba trăm năm mươi sáu tỷ, gấp khoảng mười lần. Nói đơn giản, đây là tiền từ mua bán máy bay và động cơ, không phải tiền chở khách.'}, {'k': 'bignum', 'ch': 'Chương 3 – Bán máy bay lãi hơn chở khách', 'cap': ('BÁN MÁY BAY', 'LÃI GỘP 2.850 TỶ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': 2850, 'fmt': '{:,.0f}', 'unit': ' tỷ', 'top': 'LÃI GỘP MẢNG TÀU BAY QUÝ 3', 'sub': 'doanh thu 4.356 tỷ − giá vốn 1.506 tỷ', 'col': (34, 197, 94), 'anh': 'File:VietJet Air Airbus A321 at Hanoi Noi Bai.jpeg', 'say': 'Phần thú vị nhất nằm ở giá vốn. Mảng tàu bay có doanh thu bốn nghìn ba trăm năm mươi sáu tỷ, giá vốn chỉ khoảng một nghìn năm trăm linh sáu tỷ, tức là lãi gộp khoảng hai nghìn tám trăm năm mươi tỷ đồng. Trong khi đó, lợi nhuận gộp của toàn bộ Vietjet quý ba chỉ khoảng hai nghìn không trăm ba mươi bảy tỷ.'}, {'k': 'bignum', 'cap': ('PHẦN CÒN LẠI', 'LỖ GỘP 813 TỶ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': -813, 'fmt': '{:,.0f}', 'unit': ' tỷ', 'top': 'LÃI GỘP NGOÀI MẢNG TÀU BAY', 'sub': '≈ −111 nghìn đồng mỗi lượt khách', 'col': (239, 68, 68), 'anh': 'File:Tan Son Nhat Airport domestic hall.JPG', 'say': 'Anh chị thấy điều kỳ lạ chưa? Một mảng lãi gộp nhiều hơn cả công ty. Nếu tách riêng mảng mua bán tàu bay ra, toàn bộ phần còn lại đang lỗ gộp khoảng tám trăm mười ba tỷ đồng trong quý ba. Phần còn lại đó gồm chở khách, phụ trợ, thuê chuyến và cho thuê khô máy bay. Chia cho số khách, mỗi lượt khách lỗ khoảng một trăm mười một nghìn đồng ở khâu khai thác, trước cả chi phí bán hàng và lãi vay. Cùng kỳ năm ngoái, phần này còn lãi gộp khoảng một nghìn sáu trăm sáu mươi tỷ.'}, {'k': 'cards', 'ch': 'Chương 4 – Vì sao bay lại lỗ?', 'cap': ('CHI PHÍ BAY', 'TĂNG NHANH HƠN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Refueling, ILA 2024, Schoenefeld (ILA45423).jpg', 'cards': [('+24,5%', 'chi phí khai thác bay', ''), ('+2,4%', 'số chuyến bay', ''), ('−12,5%', 'tiền vé mỗi lượt khách', '')], 'say': 'Vậy vì sao bay lại lỗ? Chi phí khai thác bay quý ba khoảng mười bảy nghìn chín trăm tám mươi sáu tỷ, tăng hai mươi bốn phẩy năm phần trăm, trong khi số chuyến chỉ tăng hai phẩy bốn phần trăm. Chính Vietjet giải trình rằng căng thẳng ở Trung Đông giữ giá nhiên liệu bay ở mức cao trong kỳ. Một bên chi phí mỗi chuyến tăng, một bên tiền vé mỗi khách giảm, hai lưỡi kéo cắt vào giữa.'}, {'k': 'cards', 'cap': ('MỘT CHUYẾN BAY', 'THU ÍT HƠN CHI?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:VietJet Air Airbus A321 at Hanoi Noi Bai.jpeg', 'cards': [('≈187 khách', 'trung bình mỗi chuyến quý 3', ''), ('≈430 triệu đ', 'thu từ vận tải mỗi chuyến', ''), ('≈461 triệu đ', 'chi phí khai thác mỗi chuyến', '')], 'say': 'Nhìn ở góc một chuyến bay cho dễ hình dung. Quý ba có khoảng ba mươi chín nghìn chuyến, trung bình mỗi chuyến chở khoảng một trăm tám mươi bảy khách. Em chia thô toàn bộ doanh thu vận tải, gồm vé, phụ trợ và thuê chuyến, cho số chuyến, mỗi chuyến thu về khoảng bốn trăm ba mươi triệu đồng. Còn chi phí khai thác bay chia cho số chuyến là khoảng bốn trăm sáu mươi mốt triệu đồng. Tức là trung bình mỗi lần cất cánh, hãng hụt khoảng ba mươi mốt triệu đồng, chưa tính khấu hao, bán hàng và lãi vay.'}, {'k': 'text', 'cap': ('CẢ NGÀNH', 'CÙNG CHỊU'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Aircraft of VietjetAir, Vietnam Airlines and Cambodia Angkor Air.jpg', 'the': [{'f': 0.05, 'so': '145 tỷ', 'nhan': 'Lãi Vietnam Airlines quý 3/2026, −76,5%'}, {'f': 0.5, 'so': '12,5% → 7,3%', 'nhan': 'Biên lãi gộp Vietnam Airlines, cùng kỳ → quý 3/2026'}], 'say': 'Đây không phải chuyện riêng của Vietjet. Cùng quý, Vietnam Airlines doanh thu tăng gần hai mươi chín phần trăm nhưng lãi chỉ còn một trăm bốn mươi lăm tỷ, giảm bảy mươi sáu phẩy năm phần trăm, biên lợi nhuận gộp từ mười hai phẩy năm phần trăm xuống bảy phẩy ba phần trăm. Ngoài nhiên liệu, thị trường nội địa còn có thêm hãng mới cạnh tranh. Khách Vietjet nội địa tăng chín phẩy năm phần trăm, nhưng doanh thu vé nội địa lại giảm khoảng năm phần trăm, cho thấy giá vé bình quân đã phải giảm để giữ khách.'}, {'k': 'text', 'ch': 'Chương 5 – Bán máy bay có phải ăn gian?', 'cap': ('BÁN MÁY BAY', 'CÓ PHẢI ĂN GIAN?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Vietjet Air Airbus A321-211(WL) VN-A657.jpg', 'say': 'Nhưng khoan, đừng vội nghĩ bán máy bay là chiêu làm đẹp sổ sách. Đây là mô hình Vietjet làm từ nhiều năm. Hãng đặt mua máy bay số lượng lớn trực tiếp từ nhà sản xuất nên được giá tốt. Sau đó hãng bán lại cho các công ty cho thuê máy bay, rồi thuê lại chính những chiếc đó để khai thác. Khoản chênh lệch là lợi nhuận thật, là tiền thật, hoàn toàn hợp pháp.'}, {'k': 'text', 'cap': ('GIỐNG MUA SỈ', 'BÁN LẺ RỒI THUÊ LẠI'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Vietjet Air VN-A687 09-07-2024.jpg', 'anh_them': ['File:Vietjet Air Airbus A321-271N (A321neo) reg. VN-A674.jpg'], 'say': 'Anh chị hình dung thế này. Một người mua sỉ mười căn hộ từ chủ đầu tư với giá chiết khấu, bán lại từng căn cho nhà đầu tư khác với giá thị trường, rồi ký hợp đồng thuê lại chính những căn đó để ở. Người đó vừa có tiền chênh lệch, vừa không phải bỏ ra một khoản vốn khổng lồ. Vietjet làm điều tương tự với máy bay. Điểm khác là đổi lại, hãng phải trả tiền thuê đều đặn nhiều năm, và chi phí thuê đó nằm trong chi phí khai thác bay mà mình vừa thấy đang tăng.'}, {'k': 'cards', 'cap': ('LỢI NHUẬN THẬT', 'NHƯNG KHÔNG ĐỀU'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:VietJet Air aircraft at Phu Bai International Airport.jpg', 'cards': [('435 tỷ', 'doanh thu tàu bay quý 3/2025', ''), ('4.356 tỷ', 'doanh thu tàu bay quý 3/2026', ''), ('46,9 lần', 'P/E hiện tại', '')], 'say': 'Vấn đề nằm ở chất lượng. Lợi nhuận từ chở khách lặp lại mỗi ngày, có thể dự đoán. Còn lợi nhuận từ mua bán tàu bay phụ thuộc lịch giao máy bay và từng hợp đồng, quý này bốn nghìn ba trăm năm mươi sáu tỷ, quý trước có thể rất khác. Trong khi đó, giá cổ phiếu đang tương đương khoảng bốn mươi bảy lần lợi nhuận bốn quý gần nhất. Tức là thị trường đang đặt cược lớn vào việc mảng bay sẽ hồi phục khi giá nhiên liệu dịu lại, chứ không trả tiền cho mức lãi hiện tại.'}, {'k': 'bars', 'cap': ('LÃI TỪNG QUÝ', 'LÊN XUỐNG MẠNH'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Tan Son Nhat International Airport, at night.jpg', 'tag': 'LỢI NHUẬN SAU THUẾ CÔNG TY MẸ (TỶ ĐỒNG)', 'bars': [('Q4/25', 510, (56, 189, 248), '510'), ('Q1/26', 1014, (34, 197, 94), '1.014'), ('Q2/26', 334, (255, 196, 0), '334'), ('Q3/26', 347, (255, 196, 0), '347')], 'say': 'Nhìn lợi nhuận bốn quý gần nhất cũng thấy sự thất thường này. Quý bốn năm ngoái khoảng năm trăm mười tỷ, quý một năm nay vọt lên hơn một nghìn tỷ, rồi quý hai và quý ba chỉ còn quanh ba trăm bốn mươi tỷ mỗi quý. Lũy kế chín tháng, lợi nhuận hợp nhất một nghìn bảy trăm hai mươi mốt tỷ, đạt tám mươi hai phần trăm kế hoạch năm. Con số kế hoạch thì ổn, nhưng nhịp lợi nhuận rất không đều.'}, {'k': 'cards', 'cap': ('NẾU TIỀN VÉ', 'VỀ NHƯ NĂM NGOÁI?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Vietjet Air Airbus A321-271N (A321neo) reg. VN-A674.jpg', 'cards': [('+0,15 triệu đ', 'tiền vé mỗi lượt về mức 1,19 triệu', ''), ('× 7,3 triệu lượt', 'giữ số khách như quý 3', ''), ('≈ +1.100 tỷ/quý', 'đủ bù khoản lỗ gộp 813 tỷ', '')], 'say': 'Em thử làm một phép tính để thấy độ nhạy của ngành này. Giả sử số khách giữ nguyên bảy phẩy ba triệu lượt mỗi quý, nhưng tiền vé mỗi lượt quay lại mức một phẩy mười chín triệu đồng như năm ngoái. Mỗi lượt khách thu thêm khoảng một trăm năm mươi nghìn đồng, cả quý thêm khoảng một nghìn một trăm tỷ đồng doanh thu. Con số đó đủ để xóa khoản lỗ gộp tám trăm mười ba tỷ của mảng bay.'}, {'k': 'cards', 'cap': ('150 NGHÌN MỘT VÉ', 'ĐỔI CẢ BỨC TRANH'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Tan Son Nhat Airport domestic hall.JPG', 'cards': [('150 nghìn đ', 'chênh lệch mỗi tấm vé', ''), ('−813 tỷ → ≈ +280 tỷ', 'lãi gộp mảng bay (giả định)', '')], 'say': 'Chỉ chênh khoảng một trăm năm mươi nghìn đồng một tấm vé, mảng bay đã đổi từ lỗ gộp sang lãi gộp. Hàng không là ngành biên lợi nhuận rất mỏng, nên một thay đổi nhỏ của giá vé hay giá nhiên liệu cũng làm lợi nhuận đảo chiều. Đó vừa là cơ hội, vừa là rủi ro, và là lý do giá cổ phiếu hàng không thường biến động mạnh hơn lợi nhuận hiện tại.'}, {'k': 'checklist', 'ch': 'Chương 6 – Ba câu hỏi trước con số doanh thu', 'cap': ('3 CÂU HỎI', 'KHI DOANH THU TĂNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Tan Son Nhat International Terminal (08.2026).jpg', 'items': [('Doanh thu tăng nhờ mảng nào?', (255, 196, 0)), ('Mảng chính còn lãi gộp không?', (255, 196, 0)), ('Lãi có đều đặn mỗi quý không?', (255, 196, 0))], 'say': 'Từ câu chuyện Vietjet, anh chị có ba câu hỏi dùng được cho mọi doanh nghiệp. Một, doanh thu tăng nhờ mảng nào? Anh chị đừng dừng ở dòng tổng, hãy mở thuyết minh doanh thu, thường nằm gần cuối báo cáo tài chính. Hai, mảng kinh doanh chính còn lãi gộp không, hay đang được một mảng khác gánh? Ba, khoản lãi đó có đều đặn mỗi quý không, hay phụ thuộc vài giao dịch lớn? Doanh nghiệp tốt là doanh nghiệp mà mảng chính tự nuôi được mình.'}, {'k': 'checklist', 'cap': ('3 CÂU HỎI', 'KHI DOANH THU TĂNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Tan Son Nhat International Terminal (08.2026).jpg', 'items': [('Doanh thu tăng nhờ mảng nào?', (255, 196, 0)), ('Mảng chính còn lãi gộp không?', (255, 196, 0)), ('Lãi có đều đặn mỗi quý không?', (255, 196, 0))], 'say': 'Với Vietjet, điều đáng theo dõi trong vài quý tới là phần còn lại ngoài mảng tàu bay có quay lại lãi gộp hay không. Công ty cho biết giá nhiên liệu đã có dấu hiệu cải thiện so với giai đoạn trước. Bảng lợi nhuận từng quý, P trên E của Vietjet và hơn bốn trăm mã khác, em cập nhật trên chứng khoán Huy Nguyễn chấm com.'}, {'k': 'text', 'cta': 1, 'label': 'NGUỒN SỐ LIỆU', 'cap': ('THUYẾT MINH BCTC', 'QUÝ 3/2026'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Số liệu trong video lấy từ báo cáo tài chính hợp nhất quý ba năm hai nghìn không trăm hai mươi sáu và văn bản giải trình của Vietjet, các phép chia mỗi lượt khách là em tính thô để dễ hình dung. Anh chị muốn trao đổi riêng về danh mục thì nhắn Zalo không ba sáu năm, một tám tám, hai tám sáu.'}, {'k': 'end', 'cap': ('VÉ RẺ ĐI', 'HAY ĐẮT LÊN?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Còn anh chị, lần gần nhất đi máy bay, anh chị thấy giá vé rẻ đi hay đắt lên, và anh chị có trả thêm tiền hành lý, chọn chỗ không? Anh chị kể cho em nghe ở phần bình luận nhé?'}]
META = {'CH0412A': {'kenh': '@chungkhoanhuynguyen', 'seri': 'Doanh nghiệp kiếm tiền thế nào', 'ngay': '2026-12-04', 'gio_goi_y': '19:30', 'gio': '19:30', 'nhac': 'lofi', 'tieu_de': 'Hòa Phát Bán 1 Tấn Thép Lãi Bao Nhiêu? Nghịch Lý P/E THẤP Của Cổ Phiếu Chu Kỳ', 'mo_ta': 'Quý 3/2026 Hòa Phát lãi 8.265 tỷ đồng, gấp đôi cùng kỳ, nhưng cổ phiếu thấp hơn đỉnh tháng 2 khoảng 20%. Video tách lợi nhuận thành sản lượng (Dung Quất 2) và lãi mỗi tấn, chỉ ra khoản 4.929 tỷ thu từ bán công ty con, bốn mối lo của thị trường và bài học chu kỳ 2021–2022 (lãi 34.521 tỷ rồi còn 8.444 tỷ). Cuối video: 3 câu hỏi cho mọi cổ phiếu chu kỳ.\n\nChương:\n00:00 Mở đầu\n{CHUONG}\n\nBảng P/E, lợi nhuận từng quý 400+ mã cập nhật mỗi phiên: https://chungkhoanhuynguyen.com\n📂 Thư viện bài học: https://chungkhoanhuynguyen.com/hoc/\n\nNguồn số liệu: BCTC hợp nhất quý 3/2026 và bán niên 2026 của Hòa Phát, công bố KQKD 9 tháng 2026 (29/10/2026), BCTN 2022 và bản tin IR quý 4/2022, Quyết định 1959/QĐ-BCT, công báo Mexico 3/9/2026, số liệu Hải quan 9 tháng 2026. Phép chia mỗi tấn là tính thô trên tổng doanh thu/lợi nhuận.\nCần trao đổi riêng về danh mục: Zalo 0365.188.286\nChia sẻ góc nhìn, không phải khuyến nghị mua bán.', 'tags': ['Hòa Phát', 'HPG', 'cổ phiếu thép', 'Dung Quất 2', 'cổ phiếu chu kỳ', 'P/E là gì', 'doanh nghiệp kiếm tiền như thế nào', 'đọc báo cáo tài chính'], 'bia_hook': ['LÃI GẤP ĐÔI', 'GIÁ GIẢM 20%?'], 'badge': 'HÒA PHÁT QUÝ 3', 'fb_post': 'Hòa Phát quý 3 lãi 8.265 tỷ, gấp đôi cùng kỳ. Cổ phiếu thì thấp hơn đỉnh tháng 2 khoảng 20% 🤔\n\n👉 Mỗi tấn thép giữ lại ~2,17 triệu đồng lợi nhuận (tính thô), năm ngoái ~1,62 triệu\n👉 Lãi gấp đôi = sản lượng ×1,54 (Dung Quất 2) × lãi mỗi tấn ×1,34 (giá, chi phí)\n👉 9 tháng có 4.929 tỷ thu từ bán công ty con – không phải tiền bán thép\n👉 Năm 2021 Hòa Phát lãi kỷ lục 34.521 tỷ, năm 2022 còn 8.444 tỷ\n\nCổ phiếu chu kỳ có một nghịch lý: P/E thấp nhất thường xuất hiện đúng lúc lợi nhuận ở đỉnh. Video có 3 câu hỏi để soi trước khi mua.\n\n🎬 Xem đầy đủ: {LINK}\nGửi cho người bạn đang thấy "thép rẻ quá" 😄', 'chuong': ['Mở đầu', 'Chương 1 – Một tấn thép giữ lại bao nhiêu?', 'Chương 2 – Hai động cơ của lãi gấp đôi', 'Chương 3 – Khoản lãi không lặp lại', 'Chương 4 – Thị trường đang lo điều gì?', 'Chương 5 – Bài học năm 2022', 'Chương 6 – Lần này khác ở đâu?', 'Chương 7 – Ba câu hỏi cho cổ phiếu chu kỳ'], 'title': 'Hòa Phát Bán 1 Tấn Thép Lãi Bao Nhiêu? Nghịch Lý P/E THẤP Của Cổ Phiếu Chu Kỳ'}, 'CH0512A': {'kenh': '@chungkhoanhuynguyen', 'seri': 'Doanh nghiệp kiếm tiền thế nào', 'ngay': '2026-12-05', 'gio_goi_y': '19:30', 'gio': '19:30', 'nhac': 'lofi', 'tieu_de': 'Vietjet Doanh Thu TĂNG 35% Mà Tiền Vé Lại Giảm: Lợi Nhuận Thật Sự Đến Từ Đâu?', 'mo_ta': 'Quý 3/2026 Vietjet chở ~7,3 triệu lượt khách, lãi 348 tỷ – khoảng 48 nghìn đồng mỗi khách. Doanh thu tăng 35% nhưng tiền vé giảm 9,6%: phần tăng đến từ mua bán tàu bay (4.356 tỷ, gấp 10 lần). Mở thuyết minh doanh thu và giá vốn: mảng tàu bay lãi gộp ~2.850 tỷ, phần còn lại lỗ gộp ~813 tỷ. Vì sao bay lại lỗ, bán máy bay có phải "ăn gian", và 3 câu hỏi khi thấy doanh thu tăng.\n\nChương:\n00:00 Mở đầu\n{CHUONG}\n\nBảng lợi nhuận từng quý, P/E 400+ mã cập nhật mỗi phiên: https://chungkhoanhuynguyen.com\n📂 Thư viện bài học: https://chungkhoanhuynguyen.com/hoc/\n\nNguồn số liệu: BCTC hợp nhất quý 3/2026 của Vietjet (thuyết minh 26, 27), văn bản giải trình KQKD quý 3/2026 (2/11/2026), BCTC quý 3/2026 Vietnam Airlines. Phép chia mỗi lượt khách là tính thô.\nCần trao đổi riêng về danh mục: Zalo 0365.188.286\nChia sẻ góc nhìn, không phải khuyến nghị mua bán.', 'tags': ['Vietjet', 'VJC', 'cổ phiếu hàng không', 'hàng không giá rẻ', 'doanh nghiệp kiếm tiền như thế nào', 'thuyết minh báo cáo tài chính', 'đọc báo cáo tài chính', 'Vietnam Airlines'], 'bia_hook': ['BAY 1 KHÁCH', 'LÃI 48 NGHÌN?'], 'badge': 'VIETJET QUÝ 3', 'fb_post': 'Quý 3 Vietjet chở ~7,3 triệu lượt khách, lãi 348 tỷ. Chia ra: mỗi khách ~48 nghìn đồng, chưa bằng bát phở + ly cà phê sân bay ✈️\n\n👉 Doanh thu +35% mà khách chỉ +3,3%, tiền vé còn giảm 9,6%\n👉 Phần tăng chủ yếu từ mua bán tàu bay: 4.356 tỷ, gấp ~10 lần cùng kỳ, lãi gộp ~2.850 tỷ\n👉 Tách mảng này ra, phần còn lại (chở khách, phụ trợ, thuê chuyến…) lỗ gộp ~813 tỷ\n👉 Cứ 1 đồng tiền vé, hãng thu thêm gần 8 hào từ hành lý, chọn chỗ, suất ăn\n\nKhông phải "ăn gian" – đó là mô hình nhiều năm của hãng – nhưng lợi nhuận từ bán máy bay không đều như lợi nhuận từ bay.\n\n🎬 Xem đầy đủ: {LINK}\nGửi cho người bạn hay săn vé 0 đồng 😄', 'chuong': ['Mở đầu', 'Chương 1 – Một tấm vé chia làm mấy phần?', 'Chương 2 – Doanh thu tăng 35% đến từ đâu?', 'Chương 3 – Bán máy bay lãi hơn chở khách', 'Chương 4 – Vì sao bay lại lỗ?', 'Chương 5 – Bán máy bay có phải ăn gian?', 'Chương 6 – Ba câu hỏi trước con số doanh thu'], 'title': 'Vietjet Doanh Thu TĂNG 35% Mà Tiền Vé Lại Giảm: Lợi Nhuận Thật Sự Đến Từ Đâu?'}}
